import java.util.ArrayList;
import java.util.List;

public class Main {
    private static final List<byte[]> RETAINED = new ArrayList<>();
    public static void main(String[] args) {
        for (int i = 0; i < 20; i++) RETAINED.add(new byte[256 * 1024]);
        System.out.println("Retained buffers: " + RETAINED.size());
        RETAINED.clear();
        System.out.println("Application references cleared; collection timing is JVM-controlled.");
    }
}
